<div class="form-group"><label for="position">Jabatan</label><select id="position" name="position" required><option value="">Pilih Jabatan</option><?php foreach(['Cashier', 'Warehouse Staff', 'Admin'] as $option):?><option value="<?=e($option)?>" <?=(($data['position'] ?? '')===$option)?'selected':''?>><?=e($option)?></option><?php endforeach?></select><?php if(isset($errors['position'])):?><p class="error-text"><?=e($errors['position'])?></p><?php endif?></div>
